def _labels(values):
    out = []
    for value in values or []:
        if isinstance(value, dict):
            label = value.get("label") or value.get("value") or value.get("id")
        else:
            label = value
        if label and label not in out:
            out.append(str(label))
    return out

def _salary_text(salary):
    if not isinstance(salary, dict):
        return None
    cur = salary.get("currency") or {}
    period = salary.get("period") or {}
    currency = cur.get("value") or cur.get("label")
    period_text = period.get("label") or period.get("value")
    lo = salary.get("minValue")
    hi = salary.get("maxValue")
    if lo is None and hi is None:
        return None
    if lo is not None and hi is not None and lo != hi:
        text = "%s %s - %s" % (currency or "", lo, hi)
    else:
        text = "%s %s" % (currency or "", lo if lo is not None else hi)
    if period_text:
        text = text.strip() + " per " + str(period_text)
    return text.strip()

def _description(row):
    parts = []

    def add(label, values):
        if values is None or values == [] or values == "":
            return
        if isinstance(values, list):
            values = ", ".join([str(v) for v in values if v])
        if values:
            parts.append(label + ": " + str(values))

    add("Title", row.get("title"))
    add("Company", row.get("companyName") or row.get("companyId"))
    add("Company domain", row.get("companyDomain"))
    add("Locations", row.get("locations") or [])
    add("Departments", row.get("departments") or [])
    add("Job functions", _labels(row.get("jobFunctions")))
    add("Job types", _labels(row.get("jobTypes")))
    add("Seniorities", _labels(row.get("jobSeniorities") or row.get("considerLevels")))
    add("Markets", _labels(row.get("markets")))
    add("Stages", _labels(row.get("stages")))
    add("Regions", _labels(row.get("regions")))
    add("Required skills", _labels(row.get("requiredSkills")))
    add("Preferred skills", _labels(row.get("preferredSkills")))
    add("Skills", _labels(row.get("skills")))
    add("Minimum years experience", row.get("minYearsExp"))
    add("Maximum years experience", row.get("maxYearsExp"))
    add("Workplace", "remote" if row.get("remote") else ("hybrid" if row.get("hybrid") else None))
    add("Compensation", _salary_text(row.get("salary")))
    add("Source posting", row.get("url") or row.get("applyUrl"))
    add("Apply URL", row.get("applyUrl"))
    return "\n".join(parts)

def _job_url(row):
    company = row.get("companySlug")
    job_id = row.get("jobId")
    if company and job_id:
        return urljoin(SITE, "/companies/%s/jobs/%s" % (company, job_id))
    return SITE

def crawl(ctx):
    rows = json.loads(ROWS_JSON)
    seen = set()
    for row in rows:
        title = row.get("title")
        company = row.get("companyName") or row.get("companyId")
        job_id = row.get("jobId")
        if not title or not company or not job_id or job_id in seen:
            continue
        seen.add(job_id)

        locations = [str(x) for x in (row.get("locations") or []) if x]
        description = _description(row)
        if not description:
            continue

        job = {
            "url": _job_url(row),
            "title": title,
            "company": company,
            "location": locations[0] if locations else "Remote",
            "locations": locations or None,
            "description": description,
            "source": SITE,
            "external_id": str(job_id),
            "apply_url": row.get("applyUrl") or row.get("url"),
            "department": ", ".join(row.get("departments") or []) or None,
            "posted_at": row.get("timeStamp"),
        }

        if row.get("remote"):
            job["workplace_type"] = "remote"
        elif row.get("hybrid"):
            job["workplace_type"] = "hybrid"

        salary = row.get("salary") or {}
        currency = (salary.get("currency") or {}).get("value") or (salary.get("currency") or {}).get("label")
        period = (salary.get("period") or {}).get("value") or (salary.get("period") or {}).get("label")
        if salary.get("minValue") is not None:
            job["salary_min"] = salary.get("minValue")
        if salary.get("maxValue") is not None:
            job["salary_max"] = salary.get("maxValue")
        if currency:
            job["salary_currency"] = currency
        if period:
            job["salary_period"] = period
        text_salary = _salary_text(salary)
        if text_salary:
            job["salary"] = text_salary

        yield {k: v for k, v in job.items() if v not in (None, "", [])}
